"""H2 — payload parity between build_action_plan and Executor.

Pins CONTRACT.md invariant 10: ``core.planning.builder._node_payload`` and
``core.executor.engine.Executor._build_payload`` resolve graph edges into
port values with identical semantics:

  * inbound edges are read by ``(edge.source, edge.source_port)``;
  * the resolved value is assigned to ``edge.target_port``;
  * multiple incoming edges to one ``target_port`` → list;
  * a ``source_port`` that is not present in the source's outputs → None
    (never a crash).

Method: a spy WriteFileNode subclass captures the payload passed to
``dry_run`` by each caller (planner and executor). The two payloads are
then asserted equal.

CWD note: the ``exec_ctx`` fixture has its scope root at ``tmp_path``.
``validate_proposal`` (planner side) resolves relative payload paths
against CWD, so the test chdirs to ``tmp_path`` before planning. Without
this the real ScopeManager rejects e.g. ``x.txt`` as out-of-scope — a
test-environment artefact, not an edge-resolution bug.

"""

from __future__ import annotations

import pytest

from lokdocsqr.core.executor.engine import Executor
from lokdocsqr.core.models import (
    EdgeSpec,
    NodeSpec,
    NodeState,
    PolicyAction,
    PolicyDecision,
    PortSpec,
    ResolvedGraph,
    WorkflowDocument,
    WorkflowMetadata,
)
from lokdocsqr.core.planning.builder import build_action_plan
from lokdocsqr.nodes.fs_ops.write_file import WriteFileNode
from lokdocsqr.nodes.utils.path_template import PathTemplateNode


class AllowPolicy:
    def decide(self, proposal):
        return PolicyDecision(PolicyAction.ALLOW, "allow", proposal)


class _SpyWriteFile(WriteFileNode):
    """Capture the input payload of every dry_run call."""

    def __init__(self) -> None:
        super().__init__()
        self.captured: list[dict] = []

    def dry_run(self, ctx, payload):
        if isinstance(payload, dict):
            self.captured.append(dict(payload))
        else:
            self.captured.append(payload)
        path_value = payload.get("path_template") if isinstance(payload, dict) else None
        return {
            "path_template": path_value,
            "path": path_value,
            "errors": [],
            "error_count": 0,
        }


def _make_graph(case: str, n2_handler):
    n1 = NodeSpec(
        id="n1",
        type="utils.path_template",
        inputs=[PortSpec(name="template", default="x.txt")],
    )
    nodes = [n1]
    handlers = {"n1": PathTemplateNode()}
    edges = []

    if case == "single_edge":
        n2 = NodeSpec(id="n2", type="fs.write_file")
        edges.append(EdgeSpec(
            id="e1", source="n1", target="n2",
            source_port="path_template", target_port="path_template",
        ))
        nodes.append(n2)
        handlers["n2"] = n2_handler

    elif case == "missing_source_port":
        n2 = NodeSpec(id="n2", type="fs.write_file")
        edges.append(EdgeSpec(
            id="e1", source="n1", target="n2",
            source_port="not_a_real_port", target_port="path_template",
        ))
        nodes.append(n2)
        handlers["n2"] = n2_handler

    elif case == "two_incoming":
        n3 = NodeSpec(
            id="n3",
            type="utils.path_template",
            inputs=[PortSpec(name="template", default="y.txt")],
        )
        n2 = NodeSpec(id="n2", type="fs.write_file")
        edges.append(EdgeSpec(
            id="e1", source="n1", target="n2",
            source_port="path_template", target_port="path_template",
        ))
        edges.append(EdgeSpec(
            id="e2", source="n3", target="n2",
            source_port="path_template", target_port="path_template",
        ))
        nodes.extend([n3, n2])
        handlers["n3"] = PathTemplateNode()
        handlers["n2"] = n2_handler

    else:
        raise ValueError(f"unknown case {case!r}")

    doc = WorkflowDocument(
        spec_version="1.0",
        metadata=WorkflowMetadata(id="test"),
        nodes=nodes,
        edges=edges,
    )
    return ResolvedGraph(
        document=doc,
        ordered_node_ids=[node.id for node in nodes],
        handlers=handlers,
        states={node.id: NodeState.ENABLED for node in nodes},
    )


@pytest.mark.parametrize(
    "case",
    ["single_edge", "two_incoming"],
)
def test_builder_executor_edge_parity(case: str, exec_ctx, tmp_path, monkeypatch) -> None:
    # exec_ctx.scope.root == tmp_path; validate_proposal resolves relative
    # paths against CWD. Align CWD with scope root so planner-side
    # scope-check accepts the rendered path. This is a fixture-level
    # environment adjustment, not a change to the parity contract.
    monkeypatch.chdir(tmp_path)

    # Phase 1: planner — capture the payload it passes to n2.dry_run.
    planner_spy = _SpyWriteFile()
    graph = _make_graph(case, n2_handler=planner_spy)

    plan = build_action_plan(graph, exec_ctx, AllowPolicy())
    assert not plan.blocked, plan.errors
    assert len(planner_spy.captured) == 1, (
        f"planner called n2.dry_run {len(planner_spy.captured)} times, expected 1"
    )
    planner_payload = planner_spy.captured[0]

    proposal_n2 = next((p for p in plan.proposals if p.node_id == "n2"), None)
    assert proposal_n2 is not None, "planner produced no proposal for n2"
    assert proposal_n2.payload == planner_payload

    # Phase 2: executor — capture the payload it passes to n2.dry_run.
    executor_spy = _SpyWriteFile()
    graph.handlers["n2"] = executor_spy
    exec_ctx.dry_run = True
    Executor(exec_ctx).execute(graph)

    assert len(executor_spy.captured) == 1, (
        f"executor called n2.dry_run {len(executor_spy.captured)} times, expected 1"
    )
    executor_payload = executor_spy.captured[0]

    # H2 invariant: planner and executor resolve edges identically.
    assert executor_payload == planner_payload, (
        f"edge-resolution parity broken for case {case!r}: "
        f"planner={planner_payload!r}, executor={executor_payload!r}"
    )


