def test_missing_source_port_fails_closed_in_builder(exec_ctx) -> None:
    """H2-extended (partial): missing source_port in edge means the
    mutating node (fs.write_file) has no resolved path_template.

    Correct behavior is R27 fail-closed: plan.blocked=True with
    ProposalValidationError("mutating proposal with empty target_paths").
    Do NOT change this to "succeed with None payload" — that would
    silently write to a None path at execution time.

    Executor-side parity assertion is deferred to 8z: builder skips
    the edge (continue) while executor resolves to None; both
    fail-closed via validate_proposal, but through different code
    paths. Alignment is a separate invariant task (see API_CONTRACTS.md).
    """
    graph = _make_graph("missing_source_port", n2_handler=_SpyWriteFile())
    plan = build_action_plan(graph, exec_ctx, AllowPolicy())

    assert plan.blocked, (
        "missing source_port must fail-closed (R27); got "
        f"blocked={plan.blocked}, proposals={plan.proposals!r}"
    )
    assert plan.errors, "expected at least one PlanError"
    assert any(
        err.exc_type == "ProposalValidationError"
        and "empty target_paths" in err.error
        for err in plan.errors
    ), (
        "expected ProposalValidationError with 'empty target_paths', "
        f"got: {[(e.exc_type, e.error) for e in plan.errors]!r}"
    )
